using Microsoft.AspNetCore.Mvc; using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController:Controller {
 private readonly RaceDayApiClient _api; public OrganiserController(RaceDayApiClient api)=>_api=api;
 private bool Guard(){if(HttpContext.Session.GetString("Role")!="Organiser"){TempData["Error"]="Please sign in as an Organiser to access this page.";return false;}return true;}
 public async Task<IActionResult> Index(){if(!Guard())return RedirectToAction("Login","Auth");ViewBag.Events=RaceDayApiClient.CloneRoot(await _api.Get("api/events/mine"));return View();}
 [HttpGet] public IActionResult CreateEvent(){if(!Guard())return RedirectToAction("Login","Auth");return View("EventForm");}
 [HttpPost] public async Task<IActionResult> CreateEvent(string eventName,string? description,string eventType,DateTime eventDate,string location,TimeSpan startTime,IFormFile? banner){if(!Guard())return RedirectToAction("Login","Auth");var d=await _api.Post("api/events",new{eventName,description,eventType,eventDate,location,startTime});if(d==null)return View("EventForm");var bannerSaved=true;if(banner is { Length: > 0 }){var id=d.RootElement.GetProperty("eventId").GetInt32();bannerSaved=await _api.Upload($"api/media/events/{id}/banner",banner)!=null;}if(bannerSaved)TempData["Success"]="Event saved.";else TempData["Error"]="Event was created, but its banner upload failed.";return RedirectToAction(nameof(Index));}
 [HttpGet] public async Task<IActionResult> EditEvent(int id){if(!Guard())return RedirectToAction("Login","Auth");ViewBag.Event=RaceDayApiClient.CloneRoot(await _api.Get($"api/events/{id}"));return View("EventForm");}
 [HttpPost] public async Task<IActionResult> EditEvent(int id,string eventName,string? description,string eventType,DateTime eventDate,string location,TimeSpan startTime,IFormFile? banner){if(!Guard())return RedirectToAction("Login","Auth");var updated=await _api.Put($"api/events/{id}",new{eventName,description,eventType,eventDate,location,startTime});if(updated==null)return RedirectToAction(nameof(EditEvent),new{id});var bannerSaved=true;if(banner is { Length: > 0 })bannerSaved=await _api.Upload($"api/media/events/{id}/banner",banner)!=null;if(bannerSaved)TempData["Success"]="Event updated.";else TempData["Error"]="Event details were updated, but its banner upload failed.";return RedirectToAction(nameof(Index));}
 [HttpPost] public async Task<IActionResult> DeleteEvent(int id){if(!Guard())return RedirectToAction("Login","Auth");await _api.Delete($"api/events/{id}");return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Categories(int eventId){if(!Guard())return RedirectToAction("Login","Auth");ViewBag.EventId=eventId;ViewBag.Categories=RaceDayApiClient.CloneRoot(await _api.Get($"api/events/{eventId}/categories"));return View();}
 [HttpPost] public async Task<IActionResult> AddCategory(int eventId,string categoryName,decimal distanceKM,int maxParticipants,decimal entryFee){if(!Guard())return RedirectToAction("Login","Auth");await _api.Post($"api/events/{eventId}/categories",new{categoryName,distanceKM,maxParticipants,entryFee});return RedirectToAction(nameof(Categories),new{eventId});}
 [HttpPost] public async Task<IActionResult> UpdateCategory(int id,int eventId,string categoryName,decimal distanceKM,int maxParticipants,decimal entryFee){if(!Guard())return RedirectToAction("Login","Auth");await _api.Put($"api/categories/{id}",new{categoryName,distanceKM,maxParticipants,entryFee});return RedirectToAction(nameof(Categories),new{eventId});}
 [HttpPost] public async Task<IActionResult> DeleteCategory(int id,int eventId){if(!Guard())return RedirectToAction("Login","Auth");await _api.Delete($"api/categories/{id}");return RedirectToAction(nameof(Categories),new{eventId});}
 public async Task<IActionResult> Enrolments(int eventId){if(!Guard())return RedirectToAction("Login","Auth");ViewBag.EventId=eventId;ViewBag.Enrolments=RaceDayApiClient.CloneRoot(await _api.Get($"api/events/{eventId}/enrolments"));return View();}
 [HttpPost] public async Task<IActionResult> Status(int id,int eventId,string status){if(!Guard())return RedirectToAction("Login","Auth");await _api.Put($"api/enrolments/{id}/status",new{status});return RedirectToAction(nameof(Enrolments),new{eventId});}
 public async Task<IActionResult> Results(int eventId){if(!Guard())return RedirectToAction("Login","Auth");ViewBag.EventId=eventId;ViewBag.Enrolments=RaceDayApiClient.CloneRoot(await _api.Get($"api/events/{eventId}/enrolments"));ViewBag.Results=RaceDayApiClient.CloneRoot(await _api.Get($"api/events/{eventId}/results"));return View();}
 [HttpPost] public async Task<IActionResult> AddResult(int eventId,int enrolmentId,TimeSpan finishTime,int? overallPosition,int? categoryPosition){if(!Guard())return RedirectToAction("Login","Auth");await _api.Post("api/results",new{enrolmentId,finishTime,overallPosition,categoryPosition});return RedirectToAction(nameof(Results),new{eventId});}
}
